import sys
import math

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    X = int(next(it))
    Y = int(next(it))
    S = next(it).strip()
    T = next(it).strip()

    g = math.gcd(X, Y)
    # Count ones per residue class modulo g
    cntS = [0] * g
    cntT = [0] * g
    for i, ch in enumerate(S):
        if ch == '1':
            cntS[i % g] += 1
    for i, ch in enumerate(T):
        if ch == '1':
            cntT[i % g] += 1
    if cntS == cntT:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
